import java.util.*; public class Dijkstra { public static Map<String,Integer> run(Map<String,Map<String,Integer>>g,String s){Map<String,Integer>d=new HashMap<>();for(String k:g.keySet())d.put(k,Integer.MAX_VALUE);d.put(s,0);PriorityQueue<String>q=new PriorityQueue<>(Comparator.comparingInt(d::get));q.add(s);while(!q.isEmpty()){String u=q.poll();for(var e:g.getOrDefault(u,Map.of()).entrySet())if(d.get(u)!=Integer.MAX_VALUE&&d.get(e.getKey())>d.get(u)+e.getValue()){d.put(e.getKey(),d.get(u)+e.getValue());q.add(e.getKey());}}return d;} }